<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;
use App\Services\{PayrollAccess,StaffOperations,SchoolPayroll,PayrollLedger};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\Rule;
class PayrollController extends Controller {
 public function __construct(private PayrollAccess $pay,private StaffOperations $staff,private SchoolPayroll $payroll,private PayrollLedger $ledger){}
 public function setup(Request $r){return response()->json($this->staff->setup($r));}
 public function profile(Request $r,?int $id=null){$this->pay->context($r,'staff.manage');$d=$r->validate(['membership_id'=>'required|integer','employee_no'=>'required|string|max:60','designation'=>'nullable|string|max:160','hired_on'=>'nullable|date_format:Y-m-d','status'=>['required',Rule::in(['active','inactive'])]]);return response()->json($this->staff->profile($r,$d,$id));}
 public function employment(Request $r,?int $id=null){$this->pay->context($r,'staff.manage');$d=$r->validate(['staff_profile_id'=>'required|integer','campus_id'=>'required|integer','starts_on'=>'required|date_format:Y-m-d','ends_on'=>'nullable|date_format:Y-m-d|after_or_equal:starts_on','lock_version'=>'required|integer|min:0']);return response()->json($this->staff->employment($r,$d,$id));}
 public function attendance(Request $r){$d=$r->validate(['campus_id'=>'required|integer','date'=>'required|date_format:Y-m-d']);return DB::transaction(fn()=>response()->json($this->staff->attendance($r,$d['campus_id'],$d['date'])));}
 public function attendanceSave(Request $r){$this->pay->context($r,'staff.attendance');$d=$r->validate(['campus_id'=>'required|integer','date'=>'required|date_format:Y-m-d','reason'=>'nullable|string|max:1000','records'=>'required|array|min:1|max:1000','records.*.staff_profile_id'=>'required|integer|distinct','records.*.lock_version'=>'required|integer|min:0','records.*.status'=>['required',Rule::in(['present','absent','late','leave'])],'records.*.arrived_at'=>'nullable|date_format:H:i','records.*.leave_request_id'=>'nullable|integer','records.*.remarks'=>'nullable|string|max:1000']);return response()->json($this->staff->saveAttendance($r,$d));}
 public function leaves(Request $r){$r->validate(['self'=>'nullable|boolean','page'=>'nullable|integer|min:1']);if($r->boolean('self'))$this->pay->context($r,'staff.self');return response()->json($this->staff->leaves($r,$r->boolean('self')));}
 public function leaveRequest(Request $r){$this->pay->context($r);$d=$r->validate(['staff_profile_id'=>'required|integer','starts_on'=>'required|date_format:Y-m-d','ends_on'=>'required|date_format:Y-m-d|after_or_equal:starts_on','leave_type'=>['required',Rule::in(['paid','unpaid'])],'reason'=>'required|string|min:5|max:2000']);return response()->json($this->staff->requestLeave($r,$d));}
 public function leaveReview(Request $r,int $id){$this->pay->context($r);$d=$r->validate(['lock_version'=>'required|integer|min:0','action'=>['required',Rule::in(['approve','reject','cancel'])],'reason'=>'required|string|min:5|max:1000']);return response()->json($this->staff->reviewLeave($r,$id,$d));}
 public function salaries(Request $r){$d=$r->validate(['staff_profile_id'=>'required|integer']);return response()->json($this->payroll->salaries($r,$d['staff_profile_id']));}
 public function salary(Request $r){$this->pay->context($r,'payroll.manage');$d=$r->validate(['staff_profile_id'=>'required|integer','starts_on'=>'required|date_format:Y-m-d','ends_on'=>'nullable|date_format:Y-m-d|after_or_equal:starts_on','replace_previous'=>'required|boolean','items'=>'required|array|min:1|max:12','items.*.name'=>'required|string|max:120','items.*.kind'=>['required',Rule::in(['basic','allowance','deduction'])],'items.*.amount'=>'required|numeric|min:0|max:99999999.99|decimal:0,2']);return response()->json($this->payroll->salary($r,$d));}
 public function policies(Request $r){[$sid,,$campuses]=$this->pay->context($r);abort_unless($this->pay->finance($r),403);return response()->json(DB::table('payroll_policies')->where('school_id',$sid)->whereIn('campus_id',$campuses)->orderByDesc('starts_on')->get());}
 public function policy(Request $r){$this->pay->context($r,'payroll.approve');$d=$r->validate(['campus_id'=>'required|integer','starts_on'=>'required|date_format:Y-m-d','rules'=>'required|array','rules.mode'=>['required',Rule::in(['fixed','attendance'])],'rules.weekdays'=>'required|array|min:1|max:7','rules.weekdays.*'=>'required|integer|min:1|max:7|distinct','rules.deduction_basis'=>['required',Rule::in(['basic','gross'])],'rules.deduct_absence'=>'required|boolean','rules.deduct_unpaid_leave'=>'required|boolean','rules.late_per_day'=>'required|integer|min:0|max:30']);return response()->json($this->payroll->policy($r,$d));}
 public function advances(Request $r){$d=$r->validate(['campus_id'=>'required|integer']);return response()->json($this->ledger->advanceList($r,$d['campus_id']));}
 public function advance(Request $r){$this->pay->context($r,'payroll.manage');$d=$r->validate(['campus_id'=>'required|integer','staff_profile_id'=>'required|integer','requested_on'=>'required|date_format:Y-m-d','amount'=>'required|numeric|gt:0|max:99999999.99|decimal:0,2','monthly_recovery'=>'required|numeric|gt:0|max:99999999.99|decimal:0,2','reason'=>'required|string|min:5|max:2000']);return response()->json($this->ledger->advance($r,$d));}
 public function advanceAction(Request $r,int $id){$this->pay->context($r);$d=$r->validate(['lock_version'=>'required|integer|min:0','action'=>['required',Rule::in(['approve','cancel','disburse'])],'reason'=>'required_if:action,cancel|nullable|string|min:5|max:1000','paid_on'=>'required_if:action,disburse|nullable|date_format:Y-m-d','method'=>['required_if:action,disburse','nullable',Rule::in(['cash','bank','online'])],'bank_account_id'=>'nullable|integer','reference'=>'nullable|string|max:160','idempotency_key'=>'required_if:action,disburse|nullable|string|min:8|max:160']);return response()->json($this->ledger->advanceAction($r,$id,$d));}
 public function preview(Request $r){$d=$r->validate(['campus_id'=>'required|integer','month'=>'required|date_format:Y-m']);return DB::transaction(fn()=>response()->json($this->payroll->preview($r,$d['campus_id'],$d['month'])));}
 public function generate(Request $r){$this->pay->context($r,'payroll.manage');$d=$r->validate(['campus_id'=>'required|integer','month'=>'required|date_format:Y-m','source_digest'=>'required|string|size:64','run_id'=>'required|integer|min:0','lock_version'=>'required|integer|min:0']);return response()->json($this->payroll->generate($r,$d));}
 public function runs(Request $r){$d=$r->validate(['campus_id'=>'required|integer','page'=>'nullable|integer|min:1']);return response()->json($this->ledger->runs($r,$d));}
 public function run(Request $r,int $id){return DB::transaction(fn()=>response()->json($this->ledger->run($r,$id)));}
 public function approve(Request $r,int $id){$this->pay->context($r,'payroll.approve');$d=$r->validate(['lock_version'=>'required|integer|min:0']);return response()->json($this->payroll->approve($r,$id,$d));}
 public function payslip(Request $r,int $id){return DB::transaction(fn()=>response()->json($this->ledger->payslip($r,$id)));}
 public function adjustment(Request $r){$this->pay->context($r,'payroll.manage');$d=$r->validate(['payroll_item_id'=>'required|integer','kind'=>['required',Rule::in(['credit','debit','recovery_refund'])],'amount'=>'required|numeric|gt:0|max:99999999.99|decimal:0,2','advance_recovery_id'=>'nullable|integer','reason'=>'required|string|min:5|max:2000']);return response()->json($this->ledger->adjustment($r,$d));}
 public function adjustmentReview(Request $r,int $id){$this->pay->context($r,'payroll.approve');$d=$r->validate(['action'=>['required',Rule::in(['approve','reject'])],'reason'=>'required|string|min:5|max:1000']);return response()->json($this->ledger->reviewAdjustment($r,$id,$d));}
 public function payment(Request $r){$this->pay->context($r,'payroll.manage');$d=$r->validate(['campus_id'=>'required|integer','staff_profile_id'=>'required|integer','amount'=>'required|numeric|gt:0|max:99999999.99|decimal:0,2','paid_on'=>'required|date_format:Y-m-d','method'=>['required',Rule::in(['cash','bank','online'])],'bank_account_id'=>'nullable|integer','reference'=>'nullable|string|max:160','idempotency_key'=>'required|string|min:8|max:160','allocations'=>'required|array|min:1|max:24','allocations.*.payroll_item_id'=>'required|integer|distinct','allocations.*.amount'=>'required|numeric|gt:0|max:99999999.99|decimal:0,2']);return response()->json($this->ledger->payment($r,$d));}
 public function reverse(Request $r,int $id){$this->pay->context($r,'payroll.approve');$d=$r->validate(['reason'=>'required|string|min:5|max:1000']);return response()->json($this->ledger->reversePayment($r,$id,$d));}
 public function receipt(Request $r,int $id){return response()->json($this->ledger->receipt($r,$id));}
 public function self(Request $r){return response()->json($this->ledger->self($r));}
 public function history(Request $r,int $id){[$sid]=$this->pay->context($r);$run=$this->ledger->run($r,$id);$r->validate(['page'=>'nullable|integer|min:1']);$rows=DB::table('audit_logs as a')->leftJoin('school_memberships as m','m.id','=','a.actor_membership_id')->leftJoin('users as u','u.id','=','m.user_id')->where('a.school_id',$sid)->where('a.target_type','payroll_runs')->where('a.target_id',$run['run']->id)->orderByDesc('a.id')->paginate(10,['a.id','a.action','a.changes','a.occurred_at','u.name as actor_name']);foreach($rows as $row)$row->changes=json_decode($row->changes,true);return response()->json($rows);}
}
